package cat.narezany.margyt;

import android.graphics.Bitmap;
import android.graphics.BitmapFactory;
import android.util.Base64;

/**
 * The padlock artwork for the speed pill: the supplied image itself, scaled and
 * stored as PNG (alpha only, drawn tinted). No resource in the apk.
 * "Open" is the same drawing with the shackle lifted and the left leg free.
 */
final class LockArt {
    private LockArt() {}

    static final int WIDTH = 149;
    static final int HEIGHT = 200;

    private static final String CLOSED =
            "";
    private static final String OPEN =
            "";

    private static Bitmap closed;
    private static Bitmap open;

    static synchronized Bitmap get(boolean lifted) {
        if (lifted) {
            if (open == null) open = decode(OPEN);
            return open;
        }
        if (closed == null) closed = decode(CLOSED);
        return closed;
    }

    private static Bitmap decode(String data) {
        byte[] bytes = Base64.decode(data, Base64.DEFAULT);
        return BitmapFactory.decodeByteArray(bytes, 0, bytes.length);
    }
}
